package dev.feather.host

import org.junit.Assert.*
import org.junit.Test

/** Cross-language fixture: generated by Rust's actual production serializer. */
class FlatBuffersContractTest {
    @Test
    fun decodesRustLayoutWithDefaultsStylesAndTypedWidgetFields() {
        val bytes = javaClass.classLoader!!.getResourceAsStream("layout.fb")!!.use { it.readBytes() }
        val (node, errors) = parseFlatBuffersMessage(bytes, ModuleRegistry())
        assertTrue(errors.toString(), errors.isEmpty())
        val children = (node as FeatherNode.ColumnNode).children
        assertEquals(5, children.size)
        val text = children[0] as FeatherNode.TextNode
        assertEquals("Shared protocol", text.text)
        assertEquals("#123456", text.style!!.color)
        assertEquals(18, text.style!!.fontSize)
        assertEquals(0.0f, text.style!!.opacity)
        val placeholder = children[1] as FeatherNode.PlaceholderNode
        assertEquals("120", placeholder.width)
        assertEquals("80", placeholder.height)
        assertEquals(8, placeholder.cornerRadius)
        val refresh = children[2] as FeatherNode.PullToRefreshNode
        assertEquals("refresh", refresh.action)
        assertTrue(refresh.refreshing)
        assertEquals("Refresh content", (refresh.child as FeatherNode.TextNode).text)
        val custom = children[3] as FeatherNode.CustomNode
        assertEquals("test-module", custom.module)
        assertEquals("CustomView", custom.name)
        assertEquals("Typed props", custom.props.getString("title"))
        assertEquals("Count: 0", (children[4] as FeatherNode.TextNode).text)
    }
}
